 public static void Run(){var scene=EditorSceneManager.OpenScene("Assets/Scenes/Game.unity");var root=GameObject.Find("GameCanvas").transform.Find("SafeArea/CollectionRoot");captions=new List<CollectionMeshPresentation.Caption>();medium=Font("Medium");semi=Font("SemiBold");
  var name=root.Find("NameFrameArea/NameFrame");StripFrame(name);Place((RectTransform)name.parent,.20f,.755f,.80f,.84f);Caption(name.Find("Number"),26,false,false,new Color(1,.86f,.55f));Place((RectTransform)name.Find("Number"),.1f,.62f,.9f,.95f);Caption(name.Find("Name"),48,false,false,new Color(.96f,.97f,1));Place((RectTransform)name.Find("Name"),0,.03f,1,.61f);
  Place((RectTransform)root.Find("Hero"),.14f,.39f,.86f,.75f);
  var frame=root.Find("ProgressFrameArea/ProgressFrame");StripFrame(frame);Place((RectTransform)frame.parent,.085f,.325f,.915f,.385f);Surface(frame,false);Caption(frame.Find("RestorationLabel"),27,true,false,new Color(.96f,.96f,1));Place((RectTransform)frame.Find("RestorationLabel"),.055f,.14f,.21f,.86f);Caption(frame.Find("Percentage"),45,false,false,new Color(1,.89f,.61f));Place((RectTransform)frame.Find("Percentage"),.215f,.12f,.395f,.88f);var progress=frame.Find("Progress");Place((RectTransform)progress,.43f,.33f,.94f,.67f);progress.GetComponent<Image>().color=new Color(.035f,.07f,.14f,.9f);progress.GetComponent<Image>().sprite=null;var fill=progress.Find("Fill").GetComponent<Image>();fill.color=new Color(.18f,.81f,.96f);fill.sprite=null;progress.GetComponent<Image>().color=Color.clear;var trackMesh=Surface(progress,false);trackMesh.Style(new Color(.025f,.06f,.13f,.98f),new Color(.35f,.52f,.70f,.65f),12,1);fill.color=Color.clear;var fillMesh=Surface(fill.transform,false);fillMesh.Style(new Color(.10f,.82f,.96f),new Color(.20f,.85f,1,.7f),12,0);
  Caption(root.Find("Status"),23,true,false,new Color(.80f,.90f,.98f));Place((RectTransform)root.Find("Status"),.06f,.292f,.94f,.320f);
  var stage=root.Find("StageArea/FrameArea/Frame");StripFrame(stage);Place((RectTransform)root.Find("StageArea"),.035f,.135f,.965f,.285f);Surface(stage,false);
  for(int i=1;i<=5;i++){float center=.14f+(i-1)*.18f;var slot=stage.Find("Stage"+i);Place((RectTransform)slot,center-.075f,.42f,center+.075f,.91f);Caption(stage.Find("StageNumber"+i),21,true,true,Color.white);Place((RectTransform)stage.Find("StageNumber"+i),center-.085f,.275f,center+.085f,.39f);Caption(stage.Find("StageLabel"+i),28,false,true,Color.white);Place((RectTransform)stage.Find("StageLabel"+i),center-.085f,.06f,center+.085f,.255f);Lock(slot.Find("Lock"));if(i<5){var line=stage.Find("Connector"+i);Place((RectTransform)line,center+.071f,.662f,center+.109f,.668f);line.GetComponent<Image>().sprite=null;line.GetComponent<Image>().color=new Color(.36f,.66f,.88f,.6f);}slot.Find("CurrentRing").SetAsLastSibling();slot.Find("CurrentRing").GetComponent<CollectionStageRing>().color=new Color(.35f,.85f,1,.9f);slot.Find("Lock").SetAsLastSibling();}
  var message=root.Find("MessageFrameArea/MessageFrame");StripFrame(message);Place((RectTransform)message.parent,.10f,.066f,.90f,.123f);Surface(message,false);Caption(message.Find("Message"),27,true,false,new Color(.91f,.95f,1));Place((RectTransform)message.Find("Message"),.05f,.08f,.95f,.92f);
  foreach(string n in new[]{"Back","Previous","Next"}){var t=root.Find(n);var image=t.GetComponent<Image>();image.color=Color.clear;image.raycastTarget=false;t.Find("Icon").GetComponent<Image>().enabled=false;var g=Surface(t,true);t.GetComponent<Button>().targetGraphic=g;var icon=Node(t,"MeshIcon");Place(icon,.22f,.18f,.78f,.82f);var graphic=icon.GetComponent<HomeMenuIconGraphic>()??icon.gameObject.AddComponent<HomeMenuIconGraphic>();graphic.Configure(HomeMenuIcon.Chevron);graphic.color=new Color(.5f,.86f,1);if(n!="Next")icon.localRotation=Quaternion.Euler(0,0,180);var r=(RectTransform)t;r.anchorMin=r.anchorMax=new Vector2(n=="Back"?.085f:n=="Previous"?.09f:.91f,n=="Back"?.935f:.665f);r.pivot=Vector2.one*.5f;r.anchoredPosition=Vector2.zero;}
  Lock(root.Find("Hero/HeroLock"));var select=root.Find("SelectPlanet");select.GetComponent<Image>().color=Color.clear;select.GetComponent<Button>().targetGraphic=Surface(select,true);Caption(select.Find("Label"),25,false,false,new Color(.93f,.95f,1));
  var presentation=root.GetComponent<CollectionMeshPresentation>()??root.gameObject.AddComponent<CollectionMeshPresentation>();presentation.Configure(captions.ToArray());EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Debug.Log("COLLECTION_MESH_READY");EditorApplication.Exit(0);
