 static TMP_FontAsset Font(string weight){var f=AssetDatabase.LoadAssetAtPath<TMP_FontAsset>("Assets/Fonts/CosmicPopup"+weight+".asset");f.atlasPopulationMode=AtlasPopulationMode.Dynamic;f.ClearFontAssetData();if(!f.TryAddCharacters(Characters))throw new System.Exception("Collection glyph missing "+weight);f.atlasPopulationMode=AtlasPopulationMode.Static;EditorUtility.SetDirty(f);foreach(var a in f.atlasTextures)EditorUtility.SetDirty(a);return f;}
 static void StripFrame(Transform t){var fit=t.GetComponent<AspectRatioFitter>();if(fit!=null)Object.DestroyImmediate(fit);var image=t.GetComponent<Image>();image.color=Color.clear;image.raycastTarget=false;foreach(var effect in t.GetComponents<Shadow>())Object.DestroyImmediate(effect);Place((RectTransform)t,0,0,1,1);}
 static void Caption(Transform t,float size,bool body,bool copy,Color color){var old=t.GetComponent<Text>();old.enabled=false;var r=Node(t,"MeshLabel");Place(r,0,0,1,1);var tmp=r.GetComponent<TextMeshProUGUI>()??r.gameObject.AddComponent<TextMeshProUGUI>();tmp.font=body?medium:semi;tmp.fontStyle=FontStyles.Normal;tmp.enableAutoSizing=true;tmp.fontSize=size;tmp.fontSizeMax=size;tmp.fontSizeMin=16;tmp.alignment=TextAlignmentOptions.Center;tmp.color=color;tmp.raycastTarget=false;captions.Add(new CollectionMeshPresentation.Caption{source=old,target=tmp,size=size,copyColor=copy});}
 static void Lock(Transform t){t.GetComponent<Image>().enabled=false;var r=Node(t,"MeshLock");Place(r,0,0,1,1);var g=r.GetComponent<CollectionLockMeshGraphic>()??r.gameObject.AddComponent<CollectionLockMeshGraphic>();g.color=new Color(1,.86f,.57f);g.raycastTarget=false;}
 static HomeQuitMeshGraphic Surface(Transform t,bool hit){var r=Node(t,"MeshSurface");r.SetAsFirstSibling();Place(r,0,0,1,1);var g=r.GetComponent<HomeQuitMeshGraphic>()??r.gameObject.AddComponent<HomeQuitMeshGraphic>();g.Style(new Color(.035f,.075f,.16f,.89f),new Color(.27f,.70f,.91f,.75f),22,1.5f);g.raycastTarget=hit;return g;}
 static RectTransform Node(Transform t,string n){var old=t.Find(n);if(old!=null)return(RectTransform)old;var g=new GameObject(n,typeof(RectTransform),typeof(CanvasRenderer));g.transform.SetParent(t,false);return(RectTransform)g.transform;}
 static void Place(RectTransform r,float x0,float y0,float x1,float y1){r.anchorMin=new Vector2(x0,y0);r.anchorMax=new Vector2(x1,y1);r.offsetMin=r.offsetMax=Vector2.zero;}
